String normalizarAModeloDeLosCuatro(String? raw) {
  final s = (raw ?? ''). trim();
  for (final m in kCuatroModelosGemini) {
    if (m.id == s || m.subtitulo == s || m.titulo == s) {
      return m.id;
    }
  }
  final lower = s.toLowerCase();
  if (lower.contains('lite') || lower.contains('3.5')) {
    return '3.5 Flash-Lite';
  }
  if (lower.contains('hydrogen') || lower.contains('flash')) {
    return '4 Hydrogen';
  }
  if (lower.contains('3.1') || lower.contains('pro')) {
    return '3.1 Pro';
  }
  return '4 Argon';
}

// Respaldo en Isolate por si se descarga un PPTX desde un link de Google Drive en bytes
String extraerTextoPptxOptimizadoEnIsolate(List<int> bytes) {
  final archive = ZipDecoder().decodeBytes(bytes);
  final slidesBuffer = StringBuffer();

  final slideFiles = archive.files
      .where((f) =>
          f.name.startsWith('ppt/slides/slide') && f.name.endsWith('.xml'))
      .toList();

  slideFiles.sort((a, b) {
    final numA = int.tryParse(
            RegExp(r'slide(\d+)\.xml').firstMatch(a.name)?.group(1) ?? '0') ??
        0;
    final numB = int.tryParse(
            RegExp(r'slide(\d+)\.xml').firstMatch(b.name)?.group(1) ?? '0') ??
        0;
    return numA.compareTo(numB);
  });

  final regExpParrafo = RegExp(r'<a:p\b[^>]*>(.*?)</a:p>', dotAll: true);
  final regExpTexto = RegExp(r'<a:t[^>]*>(.*?)</a:t>', dotAll: true);
  final frasesGlobalesVistas = <String>{};

  for (int i = 0; i < slideFiles.length; i++) {
    final file = slideFiles[i];
    final content =
        utf8.decode(file.content as List<int>, allowMalformed: true);
    final parrafos = regExpParrafo.allMatches(content);
    final lineasSlide = <String>[];
    final vistasEnSlide = <String>{};

    for (final p in parrafos) {
      final pContent = p.group(1) ?? '';
      final textos = regExpTexto
          .allMatches(pContent)
          .map((m) => m.group(1) ?? '')
          .join('')
          .replaceAll('&amp;', '&')
          .replaceAll('&lt;', '<')
          .replaceAll('&gt;', '>')
          .replaceAll('&quot;', '"')
          .replaceAll('&apos;', "'")
          .replaceAll(RegExp(r'\s+'), ' ')
          .trim();

      if (textos.isEmpty) continue;
      lineasSlide.add(textos);
    }

    if (lineasSlide.isNotEmpty) {
      slidesBuffer.writeln('[Diapositiva ${i + 1}] ${lineasSlide.join(" • ")}');
    }
  }
  return slidesBuffer.toString().trim();
}

String leerYCodificarImagenEnIsolate(String rutaImagen) {
  final bytes = File(rutaImagen).readAsBytesSync();
  return base64Encode(bytes);
}

class EjercicioResuelto {
  final String id;
  final String? rutaImagen;
  final DateTime fecha;
  String autor;
  String modeloUsado;
  String? nombrePptUsado;
  String? instruccionAdicional;
  String? solucion;
  bool procesando;
  String estadoCola;
  int progreso;

  EjercicioResuelto({
    required this.id,
    this.rutaImagen,
    required this.fecha,
    this.autor = 'Local',
    required this.modeloUsado,
    this.nombrePptUsado,
    this.instruccionAdicional,
    this.solucion,
    this.procesando = true,
    this.estadoCola = 'En cola',
    this.progreso = 0,
  });

  Map<String, dynamic> toJson() => {
        'id': id,
        'rutaImagen': rutaImagen,
        'fecha': fecha.toIso8601String(),
        'autor': autor,
        'modeloUsado': modeloUsado,
        'nombrePptUsado': nombrePptUsado,
        'instruccionAdicional': instruccionAdicional,
        'solucion': solucion,
        'procesando': procesando,
        'estadoCola': estadoCola,
        'progreso': progreso,
      };

  factory EjercicioResuelto.fromJson(Map<String, dynamic> json) =>
      EjercicioResuelto(
        id: json['id'] ?? DateTime.now().millisecondsSinceEpoch.toString(),
        rutaImagen: json['rutaImagen'],
        fecha: DateTime.tryParse(json['fecha'] ?? '') ?? DateTime.now(),
        autor: json['autor'] ?? 'Compañero',
        modeloUsado: normalizarAModeloDeLosCuatro(json['modeloUsado']?.toString()),
        nombrePptUsado: json['nombrePptUsado'],
        instruccionAdicional: json['instruccionAdicional'],
        solucion: json['solucion'],
        procesando: json['procesando'] ?? false,
        estadoCola: json['estadoCola'] ?? 'Listo',
        progreso: (json['progreso'] as int?) ?? 100,
      );
}

class PptCompartido {
  final String id;
  final String nombre;
  final String autor;
  final String textoExtraido;
  final String? rutaLocalPdf;
  final DateTime fecha;

  PptCompartido({
    required this.id,
    required this.nombre,
    required this.autor,
    required this.textoExtraido,
    this.rutaLocalPdf,
    required this.fecha,
  });

  int get numeroDiapositivas {
    final matches = RegExp(r'\[(Diapositiva\s+|S)\d+\]').allMatches(textoExtraido).length;
    return matches > 0 ? matches : 1;
  }

  Map<String, dynamic> toJson() => {
        'id': id,
        'nombre': nombre,
        'autor': autor,
        'textoExtraido': textoExtraido,
        'rutaLocalPdf': rutaLocalPdf,
        'fecha': fecha.toIso8601String(),
      };

  factory PptCompartido.fromJson(Map<String, dynamic> json) => PptCompartido(
        id: json['id'] ?? DateTime.now().millisecondsSinceEpoch.toString(),
        nombre: json['nombre'] ?? 'Presentacion PPT',
        autor: json['autor'] ?? 'Compañero',
        textoExtraido: json['textoExtraido'] ?? '',
        rutaLocalPdf: json['rutaLocalPdf'],
        fecha: DateTime.tryParse(json['fecha'] ?? '') ?? DateTime.now(),
      );
}

