    '/storage/emulated/0/DCIM/SayCheese',
    '/storage/emulated/0/SayCheese',
    '/storage/emulated/0/Download/SayCheese',
    '/storage/emulated/0/Documents/SayCheese',
    '/storage/emulated/0/DCIM/Camera/SayCheese',
  ];

  final String _rutaRespaldoFijo =
      '/storage/emulated/0/Pictures/SayCheese/.saycheese_historial_v23.json';

  String _apiKey = const String.fromEnvironment(
    'GEMINI_API_KEY',
    defaultValue: '',
  );

  String _modeloSeleccionado = '4 Argon';
  String _nivelPensamiento = 'Alto';

  // Solo guarda modelos que hayan devuelto 404 real, NUNCA 429 temporal
  final Set<String> _modelosNoEncontrados404 = {};
  final Map<String, int> _reintentosRedPorId = {};
  String _cacheContextoPpts = '';

  String _codigoSala = '';
  String _aliasUsuario = 'felipe';
  bool _sincronizando = false;
  String _estadoSala = 'Conectado';
  int _ultimoTimestampSync = 0;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _inicializarTodo();
  }

  // Cuando el usuario vuelve de la camara o desbloquea el telefono, reanuda al instante cualquier hoja pendiente de red
  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.resumed) {
      _escanearCarpetasSayCheese(forzarMediaStore: true);
      _reintentarHojasPendientesDeRed();
      if (_colaPendientes.isNotEmpty && !_procesandoCola) {
        _ejecutarColaSecuencial();
      }
    }
  }

  void _reintentarHojasPendientesDeRed() {
    bool agrego = false;
    for (final h in _historial) {
      if (!h.procesando && h.estadoCola == 'Esperando red') {
        final intentosPrevios = _reintentosRedPorId[h.id] ?? 0;
        if (intentosPrevios >= 2) {
          h.estadoCola = 'Error';
          continue;
        }
        _reintentosRedPorId[h.id] = intentosPrevios + 1;
        h.procesando = true;
        h.solucion = null;
        h.estadoCola = 'Resolviendo ahora...';
        h.progreso = 15;
        if (!_colaPendientes.any((e) => e.id == h.id)) {
          _colaPendientes.insert(0, h);
          agrego = true;
        }
      }
    }
    if (agrego && mounted) {
      setState(() {});
      unawaited(_ejecutarColaSecuencial());
    }
  }

  OpcionModeloGemini _obtenerConfigModelo(String idBuscado) {
    for (final m in kCuatroModelosGemini) {
      if (m.id == idBuscado || m.subtitulo == idBuscado) {
        return m;
      }
    }
    if (idBuscado.toLowerCase().contains('lite')) {
      return kCuatroModelosGemini[0];
    }
    if (idBuscado.toLowerCase().contains('hydrogen') ||
        idBuscado.toLowerCase().contains('flash')) {
      return kCuatroModelosGemini[1];
    }
    if (idBuscado.toLowerCase().contains('pro')) {
      return kCuatroModelosGemini[2];
    }
    return kCuatroModelosGemini[3];
  }

  String _normalizarNombreModelo(String raw) {
    return normalizarAModeloDeLosCuatro(raw);
  }

  Future<void> _inicializarTodo() async {
    await _cargarDatosLocales();
    await _iniciarAgente();
    _solicitarPermisoNotificaciones();
    _syncTimer = Timer.periodic(const Duration(seconds: 6), (_) {
      if (_codigoSala.isNotEmpty && !_procesandoCola) {
        _sincronizarSalaCompartida(silencioso: true);
      }
    });
  }

  Future<void> _solicitarPermisoNotificaciones() async {
    try {
      await Permission.notification.request();
    } catch (_) {}
    try {
      await _notifChannel.invokeMethod('requestPermission');
    } catch (_) {}
  }

  Future<void> _actualizarNotificacionProgreso({
    required int porcentaje,
    required String titulo,
    required String detalle,
  }) async {
    if (mounted) {
      setState(() {
        _progresoActualPorcentaje = porcentaje.clamp(0, 100);
        _textoEstadoNotificacion = '$titulo ($porcentaje%) — $detalle';
      });
    }
    try {
      await _notifChannel.invokeMethod('showProgress', {
        'title': '$titulo ($porcentaje%)',
        'body': detalle,
        'progress': porcentaje.clamp(0, 100),
        'maxProgress': 100,
        'indeterminate': false,
      });
    } catch (_) {}
  }

  Future<void> _mostrarNotificacionCompletado({
    required EjercicioResuelto ejercicio,
    required bool quedanMasEnCola,
  }) async {
    final resumenLimpio = (ejercicio.solucion ?? 'Solucion lista')
        .replaceAll(RegExp(r'[#*`_~>|]'), '')
        .replaceAll(RegExp(r'\s+'), ' ')
        .trim();
    final preview = resumenLimpio.length > 110
        ? '${resumenLimpio.substring(0, 110)}...'
        : resumenLimpio;

    if (mounted) {
      setState(() {
        if (!quedanMasEnCola) {
          _progresoActualPorcentaje = 100;
          _textoEstadoNotificacion = 'Listo: $preview';
        }
      });
    }

    try {
      await _notifChannel.invokeMethod('showCompleted', {
        'title': 'Hoja resuelta (${ejercicio.modeloUsado})',
        'body': preview,
        'cancelProgress': !quedanMasEnCola,
        'id': 2000 + (ejercicio.id.hashCode.abs() % 5000),
      });
    } catch (_) {}
  }

  Future<void> _ocultarNotificacionProgreso() async {
    _progresoSimuladoTimer?.cancel();
    if (mounted) {
      setState(() {
        _progresoActualPorcentaje = 0;
        _textoEstadoNotificacion = '';
      });
    }
    try {
      await _notifChannel.invokeMethod('cancelProgress');
    } catch (_) {}
  }

  String _limpiarCodigoSala(String raw) {
    return raw
        .trim()
        .toUpperCase()
        .replaceAll(RegExp(r'\s+'), '')
        .replaceAll(RegExp(r'[^A-Z0-9-]'), '');
  }

  String get _etiquetaPptsActivos {
    if (_pptsActivos.isEmpty) return '';
    return _pptsActivos.map((p) => p.nombre).join(' + ');
  }

  // Limpia espacios redundantes pero conserva el 100% de las diapositivas y notas del PPT sin cortar ninguna diapositiva
  String _compactarTextoParaVelocidad(String raw, int maxChars) {
    final lineas = raw.split('\n');
    final sb = StringBuffer();

    for (var l in lineas) {
      l = l.replaceAll(RegExp(r'\s+'), ' ').trim();
      if (l.isEmpty) continue;
      if (sb.length + l.length + 1 > maxChars) {
        break;
      }
      sb.writeln(l);
    }
    return sb.toString().trim();
  }

  void _actualizarCacheContextoPpts() {
    if (_pptsActivos.isEmpty) {
      _cacheContextoPpts = '';
      return;
    }
    final sb = StringBuffer();
    // Conserva hasta 120,000 caracteres por PPT (cubre presentaciones completas de mas de 150 diapositivas sin cortar nada)
    final int limiteCompletoPorPpt = _pptsActivos.length == 1 ? 50000 : 30000;
    for (int i = 0; i < _pptsActivos.length; i++) {
      final p = _pptsActivos[i];
      if (p.textoExtraido.isNotEmpty) {
        final txtCompleto =
            _compactarTextoParaVelocidad(p.textoExtraido, limiteCompletoPorPpt);
        sb.writeln('=== PRESENTACIÓN PPT #${i + 1}: ${p.nombre} (CONTENIDO COMPLETO DE DIAPOSITIVAS) ===');
        sb.writeln(txtCompleto);
        sb.writeln('=== FIN PPT #${i + 1} ===\n');
      }
    }
    _cacheContextoPpts = sb.toString().trim();
  }

  String _firmaDeArchivo(File f) {
    try {
      final stat = f.statSync();
      return '${f.path}|${stat.size}|${stat.modified.millisecondsSinceEpoch ~/ 1000}';
    } catch (_) {
      return f.path;
    }
  }

  Future<void> _cargarDatosLocales() async {
    final prefs = await SharedPreferences.getInstance();
    final savedKey = prefs.getString('gemini_api_key');
    if (savedKey != null && savedKey.isNotEmpty) {
      _apiKey = savedKey;
    }

    final savedModel = prefs.getString('gemini_model_v20') ??
        prefs.getString('gemini_model');
    if (savedModel != null && savedModel.isNotEmpty) {
      _modeloSeleccionado = _normalizarNombreModelo(savedModel);
    }

    _nivelPensamiento = prefs.getString('gemini_thinking_level') ?? 'Alto';

    _codigoSala = _limpiarCodigoSala(prefs.getString('sala_compartida') ?? '');
    _aliasUsuario = prefs.getString('alias_usuario') ?? 'felipe';

    final eliminadosGuardados = prefs.getStringList('ids_eliminados_v23') ??
        prefs.getStringList('ids_eliminados_v22') ??
        prefs.getStringList('ids_eliminados_v21') ??
        [];
    _idsEliminados
      ..clear()
      ..addAll(eliminadosGuardados);

    final vistosGuardados = prefs.getStringList('firmas_vistas_v23') ??
        prefs.getStringList('firmas_vistas_v22') ??
        prefs.getStringList('archivos_vistos_v21') ??
        [];
    _firmasYaVistas
      ..clear()
      ..addAll(vistosGuardados);

    final pptsSalaJson = prefs.getString('ppts_sala_v23') ??
        prefs.getString('ppts_sala_v22') ??
        prefs.getString('ppts_sala_v21');
    if (pptsSalaJson != null && pptsSalaJson.isNotEmpty) {
      try {
        final List rawPpts = jsonDecode(pptsSalaJson);
        _pptsDeLaSala
          ..clear()
          ..addAll(rawPpts
              .map((e) => PptCompartido.fromJson(e as Map<String, dynamic>)));
      } catch (_) {}
    }

    final pptsActivosJson = prefs.getString('ppts_activos_v23') ??
        prefs.getString('ppts_activos_v22') ??
        prefs.getString('ppts_activos_v21');
    if (pptsActivosJson != null && pptsActivosJson.isNotEmpty) {
      try {
        final List rawAct = jsonDecode(pptsActivosJson);
        _pptsActivos
          ..clear()
          ..addAll(rawAct
              .map((e) => PptCompartido.fromJson(e as Map<String, dynamic>))
              .take(2));
        _actualizarCacheContextoPpts();
      } catch (_) {}
    }

    List<EjercicioResuelto> cargados = [];

    try {
      final rawUnificado = prefs.getString('historial_json_completo_v23') ??
          prefs.getString('historial_json_completo_v22') ??
          prefs.getString('historial_json_completo_v21') ??
          prefs.getString('historial_json_completo_v20');
      if (rawUnificado != null && rawUnificado.isNotEmpty) {
        final List listaRaw = jsonDecode(rawUnificado);
        cargados = listaRaw
            .map((e) => EjercicioResuelto.fromJson(e as Map<String, dynamic>))
            .where((e) => !_idsEliminados.contains(e.id))
            .toList();
      }
    } catch (_) {}

    if (cargados.isEmpty) {
      try {
        final file = File(_rutaRespaldoFijo);
        if (await file.exists()) {
          final contenido = await file.readAsString();
          if (contenido.isNotEmpty) {
            final List listaRaw = jsonDecode(contenido);
            cargados = listaRaw
                .map((e) =>
                    EjercicioResuelto.fromJson(e as Map<String, dynamic>))
                .where((e) => !_idsEliminados.contains(e.id))
                .toList();
          }
        }
      } catch (_) {}
    }

    final ahora = DateTime.now();
    for (final c in cargados) {
      c.modeloUsado = normalizarAModeloDeLosCuatro(c.modeloUsado);
      if (c.rutaImagen != null) {
        final f = File(c.rutaImagen!);
        _firmasYaVistas.add(c.rutaImagen!);
        if (f.existsSync()) {
          _firmasYaVistas.add(_firmaDeArchivo(f));
        }
      }
      // Si alguna hoja habia quedado con error de red o 404 de gemini-2.0-flash, re-encolarla automaticamente
      if (!c.procesando &&
          c.rutaImagen != null &&
          c.solucion != null &&
          (c.solucion!.contains('Failed host lookup') ||
              c.solucion!.contains('gemini-2.0-flash'))) {
        c.procesando = true;
        c.solucion = null;
        c.estadoCola = 'En cola';
        c.progreso = 10;
      }
      if (c.procesando) {
        if (ahora.difference(c.fecha).inMinutes > 5) {
          c.procesando = false;
          c.estadoCola = 'Interrumpido';
          c.solucion =
              'Resolucion interrumpida. Toca el boton 🔄 arriba a la derecha para resolverla ahora.';
        } else {
          c.estadoCola = 'En cola';
          c.progreso = 0;
          _colaPendientes.add(c);
        }
      }
    }

    if (mounted) {
      setState(() {
        _historial
          ..clear()
          ..addAll(cargados);
      });
    }

    if (_colaPendientes.isNotEmpty) {
      _ejecutarColaSecuencial();
    }

    if (_codigoSala.isNotEmpty) {
      _sincronizarSalaCompartida(silencioso: true);
    }
  }

