  Future<void> _agregarOActivarPpt({
    required String nombre,
    required String textoExtraido,
    required String autor,
    String? rutaLocalPdf,
    int? slotForzado,
    bool compartirEnSala = true,
  }) async {
    final textoOptimizado = _compactarTextoParaVelocidad(textoExtraido, 55000);
    final nuevoPpt = PptCompartido(
      id: '${nombre}_$autor',
      nombre: nombre,
      autor: autor,
      textoExtraido: textoOptimizado,
      rutaLocalPdf: rutaLocalPdf,
      fecha: DateTime.now(),
    );

    if (mounted) {
      setState(() {
        _pptsDeLaSala.removeWhere((p) => p.nombre == nombre);
        _pptsDeLaSala.insert(0, nuevoPpt);

        final idxExistente =
            _pptsActivos.indexWhere((p) => p.nombre == nombre);
        if (idxExistente != -1) {
          _pptsActivos[idxExistente] = nuevoPpt;
        } else if (slotForzado != null &&
            slotForzado >= 0 &&
            slotForzado < _pptsActivos.length) {
          _pptsActivos[slotForzado] = nuevoPpt;
        } else if (_pptsActivos.length < 2) {
          _pptsActivos.add(nuevoPpt);
        } else {
          _pptsActivos[1] = nuevoPpt;
        }
        _actualizarCacheContextoPpts();
      });
    }
    await _guardarPptsLocal();

    if (compartirEnSala &&
        _codigoSala.isNotEmpty &&
        textoOptimizado.isNotEmpty &&
        !_procesandoCola) {
      unawaited(_publicarPptEnSala(nuevoPpt));
    }
  }

  Future<void> _quitarPptPorIndice(int index) async {
