        _ultimoTimestampSync = 0;
      });
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Has salido de la sala compartida.')),
      );
    }
  }

  Future<void> _asegurarWatchersActivos() async {
    for (final ruta in _rutasVigiladas) {
      try {
        final dir = Directory(ruta);
        if (ruta == _rutaCarpeta && !await dir.exists()) {
          try {
            await dir.create(recursive: true);
          } catch (_) {}
        }
        if (await dir.exists() && !_watchersPorRuta.containsKey(ruta)) {
          final watcher = DirectoryWatcher(ruta);
          final sub = watcher.events.listen((event) {
            _verificarArchivoDetectado(File(event.path));
          }, onError: (_) {
            _watchersPorRuta.remove(ruta);
          });
          _watchersPorRuta[ruta] = sub;
        }
      } catch (_) {}
    }
  }

  Future<void> _iniciarAgente() async {
    await [
      Permission.photos,
      Permission.storage,
      Permission.manageExternalStorage,
      Permission.notification,
    ].request();

    await _asegurarWatchersActivos();
    await _escanearCarpetasSayCheese(forzarMediaStore: true);

    _pollingCarpetaTimer?.cancel();
    int tickCount = 0;
    _pollingCarpetaTimer =
        Timer.periodic(const Duration(milliseconds: 1000), (_) {
      tickCount++;
      _escanearCarpetasSayCheese(forzarMediaStore: tickCount % 3 == 0);
      if (tickCount % 3 == 0 && !_procesandoCola) {
        _reintentarHojasPendientesDeRed();
      }
    });

    if (mounted) setState(() => _agenteActivo = true);
  }

  Future<void> _escanearCarpetasSayCheese({bool forzarMediaStore = false}) async {
    if (_escaneandoAhora) return;
    _escaneandoAhora = true;

    try {
      await _asegurarWatchersActivos();

      final archivosEncontradosAhora = <String, File>{};

      for (final ruta in _rutasVigiladas) {
        try {
          final dir = Directory(ruta);
          if (!await dir.exists()) continue;
          final entidades = dir.listSync(recursive: true, followLinks: false);
          for (final ent in entidades) {
            if (ent is File) {
              archivosEncontradosAhora[ent.path] = ent;
            }
          }
        } catch (_) {}
      }

      if (forzarMediaStore) {
        try {
          final List<dynamic>? mediaPaths = await _notifChannel
              .invokeMethod<List<dynamic>>('scanSayCheeseMediaStore');
          if (mediaPaths != null) {
            for (final mp in mediaPaths) {
              final p = mp?.toString() ?? '';
              if (p.isNotEmpty && !archivosEncontradosAhora.containsKey(p)) {
                final f = File(p);
                if (f.existsSync()) {
                  archivosEncontradosAhora[p] = f;
                }
              }
            }
          }
        } catch (_) {}
      }

      if (_primerEscaneoRealizado) {
        final rutasBorradasDeCarpeta = _rutasPresentesEnUltimoEscaneo
            .difference(archivosEncontradosAhora.keys.toSet());
        if (rutasBorradasDeCarpeta.isNotEmpty) {
          for (final rutaBorrada in rutasBorradasDeCarpeta) {
            _firmasYaVistas.removeWhere(
                (firma) => firma == rutaBorrada || firma.startsWith('$rutaBorrada|'));
          }
        }
      }

      _rutasPresentesEnUltimoEscaneo
        ..clear()
        ..addAll(archivosEncontradosAhora.keys);
      _primerEscaneoRealizado = true;

      final listaArchivos = archivosEncontradosAhora.values.toList();
      listaArchivos.sort((a, b) {
        try {
          return a.lastModifiedSync().compareTo(b.lastModifiedSync());
        } catch (_) {
          return 0;
        }
      });

      for (final archivo in listaArchivos) {
        await _verificarArchivoDetectado(archivo);
      }
    } finally {
      _escaneandoAhora = false;
    }
  }

  Future<void> _verificarArchivoDetectado(File archivo) async {
    final path = archivo.path;
    final name = path.split('/').last;
    if (name.startsWith('.')) return;
    if (_rutasEnLectura.contains(path)) return;

    final pathLower = path.toLowerCase();
    final esImagen = _esArchivoDeImagenValido(path);
    final esPptOPdf =
        pathLower.endsWith('.pptx') || pathLower.endsWith('.pdf');

    if (!esImagen && !esPptOPdf) return;
    if (_colaPendientes.any((e) => e.rutaImagen == path)) return;

    _rutasEnLectura.add(path);
    try {
      if (!await archivo.exists()) return;

      int tamano = await archivo.length();
      if (tamano < 512) {
        await Future.delayed(const Duration(milliseconds: 300));
        if (!await archivo.exists()) return;
        tamano = await archivo.length();
        if (tamano < 512) {
          return;
        }
      }

      final firmaActual = _firmaDeArchivo(archivo);
      final yaVistaFirma = _firmasYaVistas.contains(firmaActual);
      final yaVistaRutaSimple = _firmasYaVistas.contains(path);

      if (yaVistaFirma) return;

      if (yaVistaRutaSimple &&
          _historial.any((h) => h.rutaImagen == path)) {
        _firmasYaVistas.add(firmaActual);
        return;
      }

      _firmasYaVistas.add(path);
      _firmasYaVistas.add(firmaActual);

      if (esImagen) {
        await _encolarNuevaFoto(archivo);
      } else if (esPptOPdf) {
        unawaited(_cargarArchivoPptOPdf(archivo));
      }
    } catch (_) {
    } finally {
      _rutasEnLectura.remove(path);
    }
  }

