  void _iniciarAnimacionProgresoNotificacion(
      EjercicioResuelto actual, int restantesEnCola) {
    _progresoSimuladoTimer?.cancel();
    _progresoSimuladoTimer =
        Timer.periodic(const Duration(milliseconds: 550), (timer) {
      if (!_procesandoCola || !actual.procesando) {
        timer.cancel();
        return;
      }
      if (actual.progreso < 92) {
        final incremento = actual.progreso < 55
            ? 10
            : (actual.progreso < 80 ? 6 : 2);
        actual.progreso = (actual.progreso + incremento).clamp(12, 92);
        final sufijoCola = restantesEnCola > 1
            ? ' • En cola: ${restantesEnCola - 1} mas'
            : '';
        final faseTexto = actual.progreso < 40
            ? 'Analizando hoja con ${actual.modeloUsado}$sufijoCola'
            : (actual.progreso < 75
                ? 'Obteniendo respuestas exactas$sufijoCola'
                : 'Finalizando respuestas directas$sufijoCola');
        _actualizarNotificacionProgreso(
          porcentaje: actual.progreso,
          titulo: 'Resolviendo hoja',
          detalle: faseTexto,
        );
      }
    });
  }

  Future<void> _ejecutarColaSecuencial() async {
    if (_procesandoCola) return;
    _procesandoCola = true;

    try {
      while (_colaPendientes.isNotEmpty) {
        final actual = _colaPendientes.first;
        if (_idsEliminados.contains(actual.id) || actual.rutaImagen == null) {
          _colaPendientes.removeAt(0);
          continue;
        }

        final totalEnColaAhora = _colaPendientes.length;

        if (mounted) {
          setState(() {
            actual.procesando = true;
            actual.progreso = 15;
            actual.estadoCola = 'Resolviendo ahora...';
          });
        }

        unawaited(_actualizarNotificacionProgreso(
          porcentaje: 15,
          titulo: 'Resolviendo hoja',
          detalle:
              'Procesando con ${actual.modeloUsado}${totalEnColaAhora > 1 ? " • En cola: ${totalEnColaAhora - 1}" : ""}...',
        ));

        final archivoFoto = File(actual.rutaImagen!);
        for (int w = 0; w < 3; w++) {
          if (await archivoFoto.exists() && await archivoFoto.length() > 512) {
            break;
          }
          await Future.delayed(const Duration(milliseconds: 150));
        }

        actual.progreso = 25;
        _iniciarAnimacionProgresoNotificacion(actual, totalEnColaAhora);

        try {
          final resultado = await _llamarGeminiUltrarrapidoSinCortes(
            archivoFoto,
            actual.modeloUsado,
            instruccionAdicional: actual.instruccionAdicional,
          );
          _progresoSimuladoTimer?.cancel();

          final quedanMas = _colaPendientes.length > 1;
          if (mounted) {
            setState(() {
              actual.solucion = _limpiarRespuestaMarkdown(resultado['texto']!);
              actual.modeloUsado = resultado['modeloFinal']!;
              actual.procesando = false;
              actual.progreso = 100;
              actual.estadoCola = 'Listo';
            });
          }

          await _actualizarNotificacionProgreso(
            porcentaje: 100,
            titulo: 'Hoja completada',
            detalle: '100% resuelto con ${actual.modeloUsado}',
          );

          await _guardarHistorialLocal();
          await _mostrarNotificacionCompletado(
            ejercicio: actual,
            quedanMasEnCola: quedanMas,
          );
          unawaited(_publicarSolucionIndividualEnSala(actual));
          _colaPendientes.removeWhere((e) => e.id == actual.id);
        } catch (e) {
          _progresoSimuladoTimer?.cancel();
          final msgErr = e.toString();
          final esFalloRedCamara = msgErr.contains('Failed host lookup') ||
              msgErr.contains('SocketException') ||
              msgErr.contains('ESPERANDO_RED');

          if (esFalloRedCamara) {
            // Si Android bloqueo temporalmente el DNS mientras la camara estaba abierta,
            // NO mostramos error feo: dejamos la hoja lista para reanudarse sola apenas vuelva la red
            if (mounted) {
              setState(() {
                actual.procesando = false;
                actual.estadoCola = 'Esperando red';
                actual.solucion =
                    '⏳ Esperando reconexión automática de red tras salir de la cámara (se resolverá sola en unos segundos o toca 🔄)...';
              });
            }
            _colaPendientes.removeWhere((e) => e.id == actual.id);
            await _guardarHistorialLocal();
            break;
          } else {
            final quedanMas = _colaPendientes.length > 1;
            if (mounted) {
              setState(() {
                actual.solucion = 'Error al resolver: $e';
                actual.procesando = false;
                actual.estadoCola = 'Error';
              });
            }
            if (!quedanMas) {
              await _ocultarNotificacionProgreso();
            }
            await _guardarHistorialLocal();
            _colaPendientes.removeWhere((e) => e.id == actual.id);
          }
        }

        if (mounted) setState(() {});
      }
    } finally {
      _progresoSimuladoTimer?.cancel();
      _procesandoCola = false;
    }
  }

  String _limpiarRespuestaMarkdown(String raw) {
    var limpio = raw.replaceAll('```markdown', '').replaceAll('```', '');
    final lineas = limpio.split('\n');
    final procesadas = lineas.map((linea) {
      if (linea.startsWith('    ') &&
          !linea.trimLeft().startsWith('*') &&
          !linea.trimLeft().startsWith('-') &&
          !linea.trimLeft().startsWith('|') &&
          !RegExp(r'^\d+\.').hasMatch(linea.trimLeft())) {
        return linea.trimLeft();
      }
      return linea;
    }).toList();
    return procesadas.join('\n').trim();
  }

  // Espera inteligentemente a que el DNS de Android despierte tras usar la camara
  Future<bool> _esperarRedDisponible({int maxIntentos = 22}) async {
    try {
      unawaited(
          _notifChannel.invokeMethod('keepNetworkAwake', {'enable': true}));
    } catch (_) {}

    for (int i = 0; i < maxIntentos; i++) {
      try {
        final res =
            await InternetAddress.lookup('generativelanguage.googleapis.com')
                .timeout(const Duration(seconds: 2));
        if (res.isNotEmpty && res.first.rawAddress.isNotEmpty) {
          return true;
        }
      } catch (_) {}
      await Future.delayed(const Duration(milliseconds: 600));
    }
    return false;
  }

