      if (res != null && res.isNotEmpty) {
        return res;
      }
    } catch (_) {}
    return compute(leerYCodificarImagenEnIsolate, path);
  }

  Future<Map<String, String>> _llamarGeminiUltrarrapidoSinCortes(
    File imagen,
    String modeloElegido, {
    String? instruccionAdicional,
  }) async {
    final keyLimpia = _apiKey.trim();
    if (keyLimpia.isEmpty) {
      throw Exception(
          'Configura tu API Key en el boton superior de modelo/ajustes.');
    }

    final base64Image = await _obtenerImagenComprimidaBase64(imagen.path);
    final configModelo = _obtenerConfigModelo(modeloElegido);
    final hayPptsActivos =
        _cacheContextoPpts.isNotEmpty || _pptsActivos.isNotEmpty;

    // Presupuesto de pensamiento equilibrado: analiza a fondo pero NUNCA se queda colgado pensando eternamente
    // cuando la imagen subida es de un tema distinto al de los PPTs cargados.
    int thinkingBudgetFinal = configModelo.baseThinkingBudget;
    if (hayPptsActivos && thinkingBudgetFinal > 768) {
      thinkingBudgetFinal = 768;
    }
    if (_nivelPensamiento == 'Bajo') {
      thinkingBudgetFinal = 0;
    } else if (_nivelPensamiento == 'Medio' && thinkingBudgetFinal > 512) {
      thinkingBudgetFinal = 512;
    }

    final String promptSinPpt =
        "Resuelve TODOS los ejercicios de esta imagen de forma DIRECTA, CONCISA y AL GRANO.\n"
        "${configModelo.instruccionExtra}\n"
        "REGLAS ESTRICTAS DE RESPUESTA:\n"
        "1. CERO INTRODUCCIONES: Prohibido escribir saludos o frases introductorias. Empieza directamente en '### Ejercicio 1' (o el numero/item correspondiente).\n"
        "2. RESPUESTAS DIRECTAS Y CORTAS: Ve directo a la respuesta exacta que el alumno debe escribir o marcar. Si pide justificar, hazlo en 1 o 2 oraciones precisas.\n"
        "3. TABLAS SOLO PARA CUADROS A RELLENAR: Usa una Tabla Markdown UNICAMENTE si en la hoja impresa aparece una tabla o cuadro vacio que se deba rellenar, dando el texto exacto para cada recuadro. Si no hay cuadro para rellenar, NO uses tablas.\n"
        "4. Usa **negrita** solo para la respuesta exacta, letra correcta o resultado final."
        "${(instruccionAdicional != null && instruccionAdicional.trim().isNotEmpty) ? '\n\n⚠️ INSTRUCCIÓN ADICIONAL PRIORITARIA DEL USUARIO:\n${instruccionAdicional.trim()}' : ''}";

    String promptConPpt = promptSinPpt;
    if (_cacheContextoPpts.isNotEmpty) {
      promptConPpt +=
          "\n\n📚 MATERIAL DE REFERENCIA (PRESENTACIONES PPT CARGADAS):\n"
          "REGLA CRÍTICA ANTI-BLOQUEO DE TEMA:\n"
          "- PASO 1 (Verificación rápida en 1 segundo): Mira primero de qué tema o asignatura trata la imagen subida.\n"
          "- SI LA IMAGEN TRATA DEL MISMO TEMA QUE LOS PPTs ADJUNTOS: Resuelve cada ejercicio basándote ESTRICTAMENTE en las definiciones, fórmulas, reglas, tablas y ejemplos de estas diapositivas como fuente primaria de verdad.\n"
          "- SI LA IMAGEN ES DE OTRO TEMA, MATERIA O UNIDAD DISTINTA A LOS PPTs: IGNORA POR COMPLETO los PPTs de abajo sin perder ni un segundo intentando relacionarlos, y resuelve la imagen directamente con tu conocimiento experto:\n"
          "$_cacheContextoPpts";
    }

    final List<Map<String, dynamic>> partsConPpt = [
      {"text": promptConPpt},
      {
        "inline_data": {
          "mime_type": "image/jpeg",
          "data": base64Image,
        }
      }
    ];

    final List<Map<String, dynamic>> partsSinPpt = [
      {"text": promptSinPpt},
      {
        "inline_data": {
          "mime_type": "image/jpeg",
          "data": base64Image,
        }
      }
    ];

    for (final p in _pptsActivos) {
      if (p.rutaLocalPdf != null && p.rutaLocalPdf!.isNotEmpty) {
        final pdfFile = File(p.rutaLocalPdf!);
        if (await pdfFile.exists()) {
          final len = await pdfFile.length();
          if (len <= 3 * 1024 * 1024) {
            final b64Pdf =
                await compute(leerYCodificarImagenEnIsolate, pdfFile.path);
            partsConPpt.add({
              "inline_data": {
                "mime_type": "application/pdf",
                "data": b64Pdf,
              }
            });
          }
        }
      }
    }

    final listaBase = hayPptsActivos
        ? configModelo.endpointsConPpt
        : configModelo.endpointsSinPpt;

    final List<String> candidatos = [];
    for (final ep in listaBase) {
      if (!_modelosNoEncontrados404.contains(ep)) {
        candidatos.add(ep);
      }
    }
    for (final respaldo in [
      'gemini-3-flash-preview',
      'gemini-2.5-flash',
      'gemini-2.5-flash-lite',
    ]) {
      if (!candidatos.contains(respaldo)) {
        candidatos.add(respaldo);
      }
    }

    final redLista = await _esperarRedDisponible(maxIntentos: 16);
    if (!redLista) {
      throw Exception('ESPERANDO_RED: Failed host lookup');
    }

    String ultimoDetalleError = '';
    bool usarModoLigeroSinPptPorTimeout = false;

    for (int idxCandidato = 0; idxCandidato < candidatos.length; idxCandidato++) {
      final modCandidato = candidatos[idxCandidato];
      // Si el primer modelo con PPTs pesados demoro demasiado o fallo, el respaldo desactiva thinkingBudget para responder al instante
      final int budgetActual =
          (idxCandidato == 0 && !usarModoLigeroSinPptPorTimeout)
              ? thinkingBudgetFinal
              : 0;

      final Map<String, dynamic> genConfig = {
        "maxOutputTokens": 8192,
        "temperature": configModelo.temperature,
      };
      if (budgetActual > 0 &&
          !modCandidato.contains('lite') &&
          (modCandidato.contains('2.5') || modCandidato.contains('3'))) {
        genConfig["thinkingConfig"] = {"thinkingBudget": budgetActual};
      }

      final partsAEnviar =
          usarModoLigeroSinPptPorTimeout ? partsSinPpt : partsConPpt;

      final Map<String, dynamic> payload = {
        "systemInstruction": {
          "parts": [
            {
              "text": (_cacheContextoPpts.isNotEmpty && !usarModoLigeroSinPptPorTimeout)
                  ? "Eres Gemini trabajando al 100% de tu capacidad analitica. Si la imagen corresponde al tema de las presentaciones PPT proporcionadas, aplica rigurosamente sus definiciones, formulas y criterios. Si la imagen es de otro tema distinto al de los PPTs, ignora los PPTs inmediatamente y resuelve la imagen directo sin demorar."
                  : "Eres Gemini trabajando al 100% de tu capacidad analitica. Resuelve cada ejercicio con precision absoluta, de forma directa y concisa."
            }
          ]
        },
        "contents": [
          {"parts": partsAEnviar}
        ],
        "generationConfig": genConfig,
      };

      final url = Uri.parse(
        'https://generativelanguage.googleapis.com/v1beta/models/$modCandidato:generateContent?key=$keyLimpia',
      );

      // Timeout agil (18s en Pro, 20s en Flash): si un modelo se queda pensando de mas por choque de temas entre PPT e imagen,
      // salta inmediatamente al siguiente sin quedarse trabajando eternamente.
      final timeoutModelo = modCandidato.contains('pro')
          ? const Duration(seconds: 18)
          : const Duration(seconds: 20);

      try {
        final res = await _httpClient
            .post(
              url,
              headers: {'Content-Type': 'application/json'},
              body: jsonEncode(payload),
            )
            .timeout(timeoutModelo);

        if (res.statusCode == 200) {
          final data = jsonDecode(res.body);
          final candidates = data['candidates'] as List? ?? [];
          if (candidates.isEmpty) {
            ultimoDetalleError = 'Respuesta vacia en ${configModelo.id}, reintentando...';
            continue;
          }
          final contentMap = candidates[0]['content'] as Map<String, dynamic>?;
          final respParts = contentMap?['parts'] as List? ?? [];
          final bufferRespuesta = StringBuffer();
          String ultimoTextoCualquiera = '';
          for (final p in respParts) {
            if (p is Map && p.containsKey('text')) {
              final t = p['text']?.toString() ?? '';
              if (t.isNotEmpty) {
                ultimoTextoCualquiera = t;
              }
              if (p['thought'] != true) {
                bufferRespuesta.writeln(t);
              }
            }
          }
          final textoCompleto = bufferRespuesta.toString().trim();
          final textoFinal = textoCompleto.isNotEmpty
              ? textoCompleto
              : ultimoTextoCualquiera.trim();

          if (textoFinal.isEmpty) {
            // Si el modelo agoto tokens pensando en el PPT de otro tema, reintentar sin thinkingBudget
            usarModoLigeroSinPptPorTimeout = true;
            continue;
          }

          return {
            'texto': textoFinal,
            'modeloFinal': configModelo.id,
          };
        } else if (res.statusCode == 400 &&
            (payload['generationConfig'] as Map)
                .containsKey('thinkingConfig')) {
          (payload['generationConfig'] as Map).remove('thinkingConfig');
          idxCandidato--; // Reintentar este mismo modelo sin thinkingConfig
          usarModoLigeroSinPptPorTimeout = true;
          continue;
        } else if (res.statusCode == 404) {
          if (modCandidato != 'gemini-2.5-flash' &&
              modCandidato != 'gemini-3-flash-preview') {
            _modelosNoEncontrados404.add(modCandidato);
          }
          ultimoDetalleError = 'Reintentando con ${configModelo.id}...';
          continue;
        } else if (res.statusCode == 429 || res.statusCode == 413 || res.statusCode >= 500) {
          ultimoDetalleError =
              'Alta demanda en ${configModelo.id} (${res.statusCode}), cambiando a motor rapido...';
          continue;
        } else {
          ultimoDetalleError =
              'Error en ${configModelo.id} (Codigo ${res.statusCode}). Toca 🔄 para reintentar.';
          break;
        }
      } on TimeoutException {
        ultimoDetalleError =
            'Tiempo agotado en ${configModelo.id}, activando respuesta rapida...';
        // Si se demoro con los PPTs de otro tema en el ultimo intento, el ultimo respaldo resuelve directo sin trabarse
        if (idxCandidato >= 1) {
          usarModoLigeroSinPptPorTimeout = true;
        }
        continue;
      } on SocketException catch (se) {
        ultimoDetalleError = 'ESPERANDO_RED: ${se.message}';
        final recupero = await _esperarRedDisponible(maxIntentos: 5);
        if (!recupero) {
          throw Exception('ESPERANDO_RED: Failed host lookup');
        }
        continue;
      } on http.ClientException {
        // Si la conexion HTTP se corto por el peso de los PPTs, pasar al siguiente candidato de inmediato
        ultimoDetalleError = 'Reconectando con ${configModelo.id}...';
        if (idxCandidato >= 1) {
          usarModoLigeroSinPptPorTimeout = true;
        }
        continue;
      } catch (e) {
        ultimoDetalleError = e.toString();
        continue;
      }
    }

    throw Exception(ultimoDetalleError.isNotEmpty
        ? ultimoDetalleError
        : 'No se pudo obtener respuesta en ${configModelo.id}. Toca 🔄 para reintentar.');
  }

