import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.net.Uri
import android.net.wifi.WifiManager
import android.os.Build
import android.os.PowerManager
import android.provider.MediaStore
import android.provider.OpenableColumns
import android.util.Base64
import io.flutter.embedding.android.FlutterActivity
import io.flutter.embedding.engine.FlutterEngine
import io.flutter.plugin.common.MethodChannel
import java.io.ByteArrayInputStream
import java.io.ByteArrayOutputStream
import java.io.File
import java.io.FileInputStream
import java.io.InputStream
import java.util.zip.ZipInputStream

class MainActivity: FlutterActivity() {
    private val NOTIF_CHANNEL = "com.saycheese.agent/notifications"
    private val PROGRESS_CHANNEL_ID = "saycheese_silent_progress_v25"
    private val DONE_CHANNEL_ID = "saycheese_silent_done_v25"
    private val PROGRESS_NOTIF_ID = 1001
    private val PICK_PPT_CODE = 9201
    private var pendingPickResult: MethodChannel.Result? = null
    private var wakeLock: PowerManager.WakeLock? = null
    private var wifiLock: WifiManager.WifiLock? = null

    @Suppress("DEPRECATION")
    override fun configureFlutterEngine(flutterEngine: FlutterEngine) {
        super.configureFlutterEngine(flutterEngine)
        val nm = getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
        ensureSilentChannels(nm)

        MethodChannel(flutterEngine.dartExecutor.binaryMessenger, NOTIF_CHANNEL).setMethodCallHandler { call, result ->
            when (call.method) {
                "requestPermission" -> {
                    if (Build.VERSION.SDK_INT >= 33) {
                        if (checkSelfPermission("android.permission.POST_NOTIFICATIONS") != PackageManager.PERMISSION_GRANTED) {
                            requestPermissions(arrayOf("android.permission.POST_NOTIFICATIONS"), 9101)
                        }
                    }
                    result.success(true)
                }
                "keepNetworkAwake" -> {
                    val enable = call.argument<Boolean>("enable") ?: true
                    setLocks(enable)
                    result.success(true)
                }
                "scanSayCheeseMediaStore" -> {
                    Thread {
                        val paths = mutableListOf<String>()
                        try {
                            val dataCol = MediaStore.Images.Media.DATA
                            val dateCol = MediaStore.Images.Media.DATE_MODIFIED
                            val projection = arrayOf(dataCol, dateCol)
                            val selection = "LOWER($dataCol) LIKE ?"
                            val selectionArgs = arrayOf("%saycheese%")
                            val sortOrder = "$dateCol DESC"
                            contentResolver.query(
                                MediaStore.Images.Media.EXTERNAL_CONTENT_URI,
                                projection,
                                selection,
                                selectionArgs,
                                sortOrder
                            )?.use { cursor ->
                                val idx = cursor.getColumnIndex(dataCol)
                                var count = 0
                                while (cursor.moveToNext() && count < 60) {
                                    if (idx >= 0) {
                                        val p = cursor.getString(idx)
                                        if (!p.isNullOrEmpty()) {
                                            paths.add(p)
                                            count++
                                        }
                                    }
                                }
                            }
                        } catch (_: Exception) {}
                        runOnUiThread { result.success(paths) }
                    }.start()
                }
                "compressImage" -> {
                    val path = call.argument<String>("path")
                    if (path == null) {
                        result.error("NO_PATH", "Ruta vacia", null)
                        return@setMethodCallHandler
                    }
                    Thread {
                        try {
                            val file = File(path)
                            val origBytes = file.readBytes()
                            if (origBytes.size <= 220 * 1024) {
