                        WifiManager.WIFI_MODE_FULL_LOW_LATENCY
                    } else {
                        WifiManager.WIFI_MODE_FULL_HIGH_PERF
                    }
                    wifiLock = wm.createWifiLock(lockType, "SayCheese::NetWifiLock").apply {
                        setReferenceCounted(false)
                    }
                }
                if (wifiLock?.isHeld == false) {
                    wifiLock?.acquire()
                }
            } else {
                if (wakeLock?.isHeld == true) wakeLock?.release()
                if (wifiLock?.isHeld == true) wifiLock?.release()
            }
        } catch (_: Exception) {}
    }

    // Extractor nativo completo y ultrarrapido en Kotlin:
    // Ignora los archivos multimedia pesados (imagenes/videos/fuentes) para tardar <0.1s,
    // pero extrae el 100% del texto de TODAS las diapositivas (ppt/slides/slide*.xml) y Notas del profesor (ppt/notesSlides/notesSlide*.xml) sin recortar nada.
    private fun extractPptxStreamFast(inputStream: InputStream): String {
        val slidesMap = mutableMapOf<Int, String>()
        val notesMap = mutableMapOf<Int, String>()
        val regexSlide = Regex("ppt/slides/slide(\\d+)\\.xml")
        val regexNote = Regex("ppt/notesSlides/notesSlide(\\d+)\\.xml")
        val regexP = Regex("<a:p\\b[^>]*>(.*?)</a:p>", RegexOption.DOT_MATCHES_ALL)
        val regexT = Regex("<a:t[^>]*>(.*?)</a:t>", RegexOption.DOT_MATCHES_ALL)
        val whitespaceRegex = Regex("\\s+")

        ZipInputStream(inputStream).use { zis ->
            var entry = zis.nextEntry
            while (entry != null) {
                val slideMatch = regexSlide.matchEntire(entry.name)
                val noteMatch = if (slideMatch == null) regexNote.matchEntire(entry.name) else null
                if (slideMatch != null || noteMatch != null) {
                    val num = (slideMatch ?: noteMatch)!!.groupValues[1].toIntOrNull() ?: 0
                    val xml = zis.readBytes().toString(Charsets.UTF_8)
                    val lines = mutableListOf<String>()
                    for (pMatch in regexP.findAll(xml)) {
                        val pContent = pMatch.groupValues[1]
                        val sb = StringBuilder()
                        for (tMatch in regexT.findAll(pContent)) {
                            sb.append(tMatch.groupValues[1])
                        }
                        val clean = sb.toString()
                            .replace("&amp;", "&")
                            .replace("&lt;", "<")
                            .replace("&gt;", ">")
                            .replace("&quot;", "\"")
                            .replace("&apos;", "'")
                            .replace(whitespaceRegex, " ")
                            .trim()
                        if (clean.isNotEmpty()) {
                            lines.add(clean)
                        }
                    }
                    if (lines.isNotEmpty()) {
                        if (slideMatch != null) {
                            slidesMap[num] = "[Diapositiva $num] " + lines.joinToString(" • ")
                        } else {
                            notesMap[num] = "(Notas Diapositiva $num: " + lines.joinToString(" • ") + ")"
                        }
                    }
                }
                zis.closeEntry()
                entry = zis.nextEntry
            }
        }
        val allSlideNums = (slidesMap.keys + notesMap.keys).toSortedSet()
        val finalLines = mutableListOf<String>()
        for (n in allSlideNums) {
            val sText = slidesMap[n] ?: ""
            val nText = notesMap[n] ?: ""
            val combined = listOf(sText, nText).filter { it.isNotEmpty() }.joinToString(" ")
            if (combined.isNotEmpty()) {
                finalLines.add(combined)
            }
        }
        return finalLines.joinToString("\n").trim()
    }

    override fun onActivityResult(requestCode: Int, resultCode: Int, data: Intent?) {
        super.onActivityResult(requestCode, resultCode, data)
        if (requestCode == PICK_PPT_CODE) {
            val res = pendingPickResult
            pendingPickResult = null
            if (res == null) return
            if (resultCode != Activity.RESULT_OK || data == null) {
                res.success(emptyList<Map<String, String>>())
                return
            }
            Thread {
                try {
                    val uris = mutableListOf<Uri>()
                    val clip = data.clipData
                    if (clip != null) {
                        val count = minOf(clip.itemCount, 2)
                        for (i in 0 until count) {
                            uris.add(clip.getItemAt(i).uri)
                        }
                    } else if (data.data != null) {
                        uris.add(data.data!!)
                    }
                    val listaArchivos = mutableListOf<Map<String, String>>()
                    for (u in uris) {
                        var nombre = "Documento_${System.currentTimeMillis()}.pptx"
                        contentResolver.query(u, null, null, null, null)?.use { cursor ->
                            if (cursor.moveToFirst()) {
                                val idx = cursor.getColumnIndex(OpenableColumns.DISPLAY_NAME)
                                if (idx >= 0) {
                                    nombre = cursor.getString(idx) ?: nombre
                                }
                            }
                        }
                        val lower = nombre.lowercase()
                        if (lower.endsWith(".pptx")) {
                            val extractedText = contentResolver.openInputStream(u)?.use { stream ->
                                extractPptxStreamFast(stream)
                            } ?: ""
                            listaArchivos.add(mapOf(
                                "name" to nombre,
                                "text" to extractedText,
                                "base64" to ""
                            ))
                        } else {
                            val bytes = contentResolver.openInputStream(u)?.use { it.readBytes() }
                            if (bytes != null && bytes.isNotEmpty()) {
                                // Intentar primero como ZIP/PPTX por si no tiene extension .pptx
                                var posibleTexto = ""
                                if (!lower.endsWith(".pdf")) {
                                    try {
                                        posibleTexto = extractPptxStreamFast(ByteArrayInputStream(bytes))
                                    } catch (_: Exception) {}
                                }
                                if (posibleTexto.isNotEmpty()) {
                                    listaArchivos.add(mapOf(
                                        "name" to nombre,
                                        "text" to posibleTexto,
                                        "base64" to ""
                                    ))
                                } else {
                                    val b64 = Base64.encodeToString(bytes, Base64.NO_WRAP)
                                    listaArchivos.add(mapOf(
                                        "name" to nombre,
                                        "text" to "",
                                        "base64" to b64
                                    ))
                                }
                            }
                        }
                    }
                    runOnUiThread { res.success(listaArchivos) }
                } catch (e: Exception) {
                    runOnUiThread { res.error("READ_ERR", e.message, null) }
                }
            }.start()
        }
    }

    private fun getLaunchPendingIntent(): PendingIntent? {
        val launchIntent = packageManager.getLaunchIntentForPackage(packageName)?.apply {
            flags = Intent.FLAG_ACTIVITY_SINGLE_TOP or Intent.FLAG_ACTIVITY_CLEAR_TOP
        } ?: return null
        val flags = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.M) {
            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
        } else {
            PendingIntent.FLAG_UPDATE_CURRENT
        }
        return PendingIntent.getActivity(applicationContext, 0, launchIntent, flags)
    }

    private fun ensureSilentChannels(nm: NotificationManager) {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            try {
                nm.deleteNotificationChannel("saycheese_progress_channel")
                nm.deleteNotificationChannel("saycheese_done_channel")
                nm.deleteNotificationChannel("saycheese_done_channel_v2")
                nm.deleteNotificationChannel("saycheese_silent_progress_v19")
                nm.deleteNotificationChannel("saycheese_silent_done_v19")
                nm.deleteNotificationChannel("saycheese_silent_progress_v20")
                nm.deleteNotificationChannel("saycheese_silent_done_v20")
                nm.deleteNotificationChannel("saycheese_silent_progress_v21")
                nm.deleteNotificationChannel("saycheese_silent_done_v21")
                nm.deleteNotificationChannel("saycheese_silent_progress_v22")
                nm.deleteNotificationChannel("saycheese_silent_done_v22")
            } catch (_: Exception) {}

            val progressChannel = NotificationChannel(
                PROGRESS_CHANNEL_ID,
                "Progreso Silencioso",
                NotificationManager.IMPORTANCE_LOW
            ).apply {
                description = "Barra de progreso sin sonido ni vibracion"
                enableVibration(false)
                vibrationPattern = longArrayOf(0L)
                setSound(null, null)
                enableLights(false)
            }
            val doneChannel = NotificationChannel(
                DONE_CHANNEL_ID,
                "Resultados Silenciosos",
                NotificationManager.IMPORTANCE_LOW
            ).apply {
                description = "Aviso 100% silencioso cuando la hoja esta lista"
                enableVibration(false)
                vibrationPattern = longArrayOf(0L)
                setSound(null, null)
                enableLights(false)
            }
            nm.createNotificationChannel(progressChannel)
            nm.createNotificationChannel(doneChannel)
        }
    }
